def get_task_log():
    node = node_by_title(doc, 'Cell window 01: Task log')
    rows = table_rows(node)
    columns = ['time', 'task', 'job', 'priority', 'CPU', 'memory', 'run time', 'event', 'machine']
    data = []
    for r in rows:
        data.append([r[1][col] for col in columns])
    return data

def get_machines():
    node = node_by_title(doc, 'Cell window 01: Machines')
    rows = table_rows(node)
    columns = ['machine', 'CPU', 'memory', 'fails at', 'returns at']
    data = []
