# Create a list of machines with their capacity
machine_caps = {}
for m in machines:
    machine_caps[m[0]] = {'cpu': int(m[1]), 'mem': int(m[2])}

# Find all tasks and their details
tasks = {}
for row in task_log:
    t_id = row[1]
    if t_id not in tasks:
        tasks[t_id] = {'cpu': int(row[4]), 'mem': int(row[5]), 'run_time': int(row[6]), 'priority': int(row[3])}

