def get_running_tasks(time):
    running = {} # machine -> [tasks]
    for m_id in machine_caps:
        running[m_id] = []

    for row in task_log:
        t_time = int(row[0])
        if t_time > time:
            break

        t_id = row[1]
        event = row[7]
        m_id = row[8]

        if event == 'start':
            # Task starts at t_time and runs for its run_time
            # It runs from t_time to t_time + run_time
            # But wait, it could be evicted or failed
            pass

    # Let's use a different approach: iterate through all events up to 'time'
    # and maintain the state of each machine.

    # Re-process task log for state at 'time'
    current_running = {} # task_id -> (machine, start_time)

    # We need to handle events in the order they happened.
    # The task log is already in time order.
    for row in task_log:
        t_time = int(row[0])
        if t_time > time:
            break

        t_id = row[1]
        event = row[7]
        m_id = row[8]

        if event == 'start':
            current_running[t_id] = (m_id, t_time)
        elif event == 'finish':
            if t_id in current_running:
                del current_running[t_id]
        elif event == 'evict':
            if t_id in current_running:
                del current_running[t_id]
        elif event == 'fail':
            if t_id in current_running:
                del current_running[t_id]

    # Now, filter tasks that are actually running at 'time'
    # A task running from start_time to start_time + run_time
    # is running at 'time' if start_time <= time < start_time + run_time
    final_running = {} # machine -> [tasks]
    for m_id in machine_caps:
        final_running[m_id] = []

    for t_id, (m_id, start_time) in current_running.items():
        run_time = tasks[t_id]['run_time']
        if start_time <= time < start_time + run_time:
            final_running[m_id].append(t_id)

    return final_running

