def get_cluster_state(window, time):
    machines_node = node_by_title(doc, f"{window}: Machines")
    tasks_node = node_by_title(doc, f"{window}: Task log")

    machines = {}
    for row in table_rows(machines_node):
        m = row[1]
        machines[m['machine']] = {
            'cpu': int(m['CPU']),
            'mem': int(m['memory']),
            'free_cpu': int(m['CPU']),
            'free_mem': int(m['memory']),
            'up': True,
            'tasks': {} # task_id: {cpu, mem, priority}
        }

    # Task log processing
    log_rows = table_rows(tasks_node)
    for row in log_rows:
        r = row[1]
        t_time = int(r['time'])
        if t_time > time:
            break

        task_id = r['task']
        event = r['event']
        machine_id = r['machine']

        if event == 'start':
            m = machines[machine_id]
            m['free_cpu'] -= int(r['CPU'])
            m['free_mem'] -= int(r['memory'])
            m['tasks'][task_id] = {
                'cpu': int(r['CPU']),
                'mem': int(r['memory']),
                'priority': int(r['priority'])
            }
        elif event == 'finish' or event == 'evict' or event == 'fail':
            if machine_id in machines:
                m = machines[machine_id]
                if task_id in m['tasks']:
                    t = m['tasks'].pop(task_id)
                    m['free_cpu'] += t['cpu']
                    m['free_mem'] += t['mem']

        # Machine failures/returns are not in task log, but in 'Events' or 'Machines'
        # Wait, the policy says: 1. Finishes, 2. Failures, 3. Returns, 4. Submissions, 5. Scheduling.
        # The task log only has task events. I need to handle machine failures.

    # Correcting for machine failures/returns from Machines table
    for row in table_rows(machines_node):
        m_info = row[1]
        m_id = m_info['machine']
        fail_time = m_info['fails at']
        return_time = m_info['returns at']

        if fail_time != '-':
            f_t = int(fail_time)
            if f_t <= time:
                machines[m_id]['up'] = False
                # Tasks on it are failed (already handled by 'fail' events in task log)
        if return_time != '-':
            r_t = int(return_time)
            if r_t <= time:
                machines[m_id]['up'] = True

    return machines

