            'cpu': get_val(m['CPU']),
            'mem': get_val(m['memory']),
            'free_cpu': get_val(m['CPU']),
            'free_mem': get_val(m['memory']),
            'up': True,
            'tasks': {}
        }

    log_rows = table_rows(tasks_node)
    for row in log_rows:
        r = row[1]
        t_time = get_val(r['time'])
        if t_time > time:
            break

        task_id = r['task']
        event = r['event']
        machine_id = r['machine']

        if event == 'start':
            m = machines[machine_id]
            m['free_cpu'] -= get_val(r['CPU'])
            m['free_mem'] -= get_val(r['memory'])
            m['tasks'][task_id] = {
                'cpu': get_val(r['CPU']),
                'mem': get_val(r['memory']),
                'priority': get_val(r['priority'])
            }
        elif event == 'finish' or event == 'evict' or event == 'fail':
            if machine_id in machines:
                m = machines[machine_id]
                if task_id in m['tasks']:
                    t = m['tasks'].pop(task_id)
                    m['free_cpu'] += t['cpu']
                    m['free_mem'] += t['mem']

    for row in table_rows(machines_node):
        m_info = row[1]
        m_id = m_info['machine']
        fail_time = get_val(m_info['fails at'])
        return_time = get_val(m_info['returns at'])

        if fail_time is not None and fail_time <= time:
            machines[m_id]['up'] = False
        if return_time is not None and return_time <= time:
            machines[m_id]['up'] = True

    return machines

