def get_tasks_on_machine_at_time(window, machine, time):
    node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(node)
    running = []
    for row_idx, row in rows:
        t_id = row['task']
        if row['machine'] == machine:
            # Find all events for this task
            events = []
            for r_idx, r in rows:
                if r['task'] == t_id:
                    events.append((int(r['time']), r['event']))

            start_time = next((t for t, e in events if e == 'start'), None)
            finish_time = next((t for t, e in events if e == 'finish'), 1201)
            if start_time is not None and start_time <= time < finish_time:
                # Need to check if it was evicted or failed
                # but for simplicity let's just see if it was running
                # (the log shows 'start' and 'finish' or 'fail'/'evict')
                # We only care about the most recent start before 'time'
                last_start = -1
                is_running = False
                for t, e in events:
                    if t > time: break
                    if e == 'start':
                        last_start = t
                        is_running = True
                    elif e in ['finish', 'fail', 'evict']:
                        is_running = False
                if is_running:
                    # Find task's CPU and Mem
                    for r_idx, r in rows:
                        if r['task'] == t_id:
                            running.append({'task': t_id, 'cpu': int(r['CPU']), 'mem': int(r['memory'])})
                            break
    return running

