def get_cluster_state(window, time):
    node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(node)

    # Machine capacities
    m_node = node_by_title(doc, f"{window}: Machines")
    m_rows = table_rows(m_node)
    machines = {}
    for r_idx, r in m_rows:
        machines[r['machine']] = {
            'cpu': int(r['CPU']),
            'mem': int(r['memory']),
            'fails': r['fails at'],
            'returns': r['returns at']
        }

    running_tasks = []
    for row_idx, row in rows:
        t_id = row['task']
        # Find all events for this task to determine if it was running at 'time'
        events = []
        for r_idx, r in rows:
            if r['task'] == t_id:
                events.append((int(r['time']), r['event'], r['machine']))

        # Sort events by time
        events.sort()

        is_running = False
        current_machine = None
        for t, e, m in events:
            if t > time:
                break
            if e == 'start':
                is_running = True
                current_machine = m
            elif e in ['finish', 'fail', 'evict']:
                is_running = False
                current_machine = None

        if is_running:
            # Get CPU/Mem from any row of this task
            for r_idx, r in rows:
                if r['task'] == t_id:
                    running_tasks.append({
                        'task': t_id,
                        'cpu': int(r['CPU']),
                        'mem': int(r['memory']),
                        'machine': current_machine
                    })
                    break

    return machines, running_tasks

