def get_cluster_state(window, time):
    node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(node)

    m_node = node_by_title(doc, f"{window}: Machines")
    m_rows = table_rows(m_node)
    machines = {}
    for r_idx, r in m_rows:
        machines[r['machine']] = {
            'cpu': int(r['CPU']),
            'mem': int(r['memory']),
            'fails': r['fails at'],
            'returns': r['returns at']
        }

    running_tasks = []
    # To avoid duplicating tasks, first build a map of task events
    tasks_events = {}
    for row_idx, row in rows:
        t_id = row['task']
        if t_id not in tasks_events:
            tasks_events[t_id] = []
        tasks_events[t_id].append((int(row['time']), row['event'], row['machine'], int(row['CPU']), int(row['memory'])))

    for t_id, events in tasks_events.items():
        events.sort()
        is_running = False
        current_machine = None
        cpu = 0
        mem = 0
        for t, e, m, c, me in events:
            if t > time:
                break
            if e == 'start':
                is_running = True
                current_machine = m
                cpu = c
                mem = me
            elif e in ['finish', 'fail', 'evict']:
                is_running = False
                current_machine = None
        if is_running:
            running_tasks.append({'task': t_id, 'cpu': cpu, 'mem': mem, 'machine': current_machine})

    return machines, running_tasks

