def get_tasks_on_machine_at_time(machine, time):
    node = node_by_title(doc, "Cell window 09: Task log")
    rows = table_rows(node)
    running = []
    for _, row in rows:
        if row['machine'] == machine:
            t_start = int(row['time']) if row['event'] == 'start' else None
            # This is tricky because we need the start time for each task.
            # Let's find the start and end events for each task on that machine.
            pass

    # Better approach:
    tasks_on_m = {}
    for _, row in rows:
        if row['machine'] == machine:
            task = row['task']
            if row['event'] == 'start':
                tasks_on_m[task] = int(row['time'])
            elif row['event'] in ['finish', 'evict', 'fail']:
                if task in tasks_on_m:
                    start_t = tasks_on_m[task]
                    if start_t <= time < int(row['time']):
                        running.append((task, start_t, int(row['time'])))
                    del tasks_on_m[task]

    for task, start_t in tasks_on_m.items():
        if start_t <= time:
            running.append((task, start_t, 1200))
    return running

