for e in events:
    t = e['time']
    task = e['task']
    event = e['event']
    machine = e['machine']

    if event == 'submit':
        task_info[task] = e
    elif event == 'start':
        occupancy[machine].add(task)
    elif event == 'finish' or event == 'fail' or event == 'evict':
        if machine in occupancy:
            occupancy[machine].discard(task)

# We need to know who is on which machine at what time.
# Let's refine the tracking.
machine_usage = {m: [] for m in machines} # list of (start, end, task)
task_starts = {}
task_ends = {}

# Re-process events to get intervals
