    t = e['time']
    task = e['task']
    event = e['event']
    machine = e['machine']
    if event == 'start':
        task_starts[task] = (t, machine)
    elif event == 'finish':
        if task in task_starts:
            start_t, mach = task_starts[task]
            machine_usage[mach].append((start_t, t, task))
            del task_starts[task]
    elif event == 'fail' or event == 'evict':
        if task in task_starts:
            start_t, mach = task_starts[task]
            machine_usage[mach].append((start_t, t, task))
            del task_starts[task]

# Also handle tasks that are still running at 1200
