def get_resources(doc, window, time):
    # Find Machines table
    machines_node = None
    for node in doc['nodes']:
        if node['title'] == f"{window}: Machines":
            machines_node = node
            break

    machine_caps = {}
    for row in machines_node['table']['rows'][1:]:
        m_id = row[0]
        machine_caps[m_id] = {
            'cpu': int(row[1]),
            'mem': int(row[2]),
            'fail': int(row[3]) if row[3] != '-' else float('inf'),
            'return': int(row[4]) if row[4] != '-' else float('inf')
        }

    # Find Task log
    task_log_node = None
    for node in doc['nodes']:
        if node['title'] == f"{window}: Task log":
            task_log_node = node
            break

    tasks_running = {m: [] for m in machine_caps}

    # Process task log up to time
    # Note: the policy order is Finishes, Failures, Returns, Submissions, Scheduling
    # But here we just want the state AFTER all events at 'time'.

    # we need to simulate the scheduling to know exactly who is running.
    # but we can also just look at the task log and filter by 'start' and 'finish'/'evict'/'fail'

    # Let's build a list of events
    events = []
    for row in task_log_node['table']['rows'][1:]:
        t = int(row[0])
        task = row[1]
        event = row[7]
        machine = row[8]
        events.append((t, task, event, machine))

    # Sort events by time
    events.sort(key=lambda x: x[0])

    running_tasks = {} # task -> machine

    for t, task, event, machine in events:
        if t > time:
            break
        if event == 'start':
            running_tasks[task] = machine
        elif event in ['finish', 'evict', 'fail']:
            if task in running_tasks:
                del running_tasks[task]

    # Now calculate usage per machine
    usage = {m: {'cpu': 0, 'mem': 0} for m in machine_caps}

    # We need the task requests.
    task_requests = {}
    for row in task_log_node['table']['rows'][1:]:
        # Use 'submit' row to get requests
        if row[7] == 'submit':
            task_requests[row[1]] = {'cpu': int(row[4]), 'mem': int(row[5])}

    for task, machine in running_tasks.items():
        req = task_requests[task]
        usage[machine]['cpu'] += req['cpu']
        usage[machine]['mem'] += req['mem']

    return machine_caps, usage

