import collections

def solve():
    task_log = []
    with open('doc_data.json', 'r') as f:
        import json
        doc = json.load(f)

    def find_node(title):
        for node in doc['nodes']:
            if node['title'] == title:
                return node
        return None

    log_node = find_node('Cell window 29: Task log')
    if not log_node:
        return "Log node not found"

    rows = log_node['table']['rows']
    cols = log_node['table']['columns']

    for row in rows:
        task_log.append(dict(zip(cols, row)))

    # Track what's on each machine at time 721
    machines_at_721 = collections.defaultdict(list)
    for event in task_log:
        time = int(event['time'])
        if time > 721:
            continue

        task = event['task']
        if event['event'] == 'start':
            machines_at_721[event['machine']].append(task)
        elif event['event'] == 'finish':
            if task in machines_at_721[event['machine']]:
                machines_at_721[event['machine']].remove(task)
        elif event['event'] == 'evict':
            if task in machines_at_721[event['machine']]:
                machines_at_721[event['machine']].remove(task)
        elif event['event'] == 'fail':
            # Machine fails, all tasks on it stop
            machines_at_721[event['machine']] = []

    return machines_at_721

